<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { ElMessage, type FormInstance, type FormRules } from 'element-plus';
import { api } from '../api';
import { subjectError } from '../subject-management';
const props=defineProps<{modelValue:boolean;vehicle?:any;options:{models:any[];enterprises:any[]}}>();
const emit=defineEmits<{'update:modelValue':[boolean];saved:[any]}>();
const visible=computed({get:()=>props.modelValue,set:(v:boolean)=>emit('update:modelValue',v)});
const isEnterprise=false,saving=ref(false),formRef=ref<FormInstance>();
const defaults=()=>({businessNo:'',vin:'',deviceNo:'',name:'',modelId:'',enterpriseId:'',color:'',vehicleType:'DELIVERY',operationScene:'URBAN_DELIVERY',upperEquipment:'',manufactureDate:'',serviceStartDate:''});
const form=reactive(defaults());
const rules:FormRules=Object.fromEntries([['businessNo','车辆编号'],['vin','VIN'],['deviceNo','设备编号'],['name','车辆名称'],['modelId','车型'],['enterpriseId','所属企业']].map(([key,label])=>[key,[{required:true,message:`请填写${label}`,trigger:'blur'}]]));
const date=(v?:string)=>v?new Date(v).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}):'';
watch(()=>props.modelValue,open=>{if(open){Object.assign(form,defaults());if(props.vehicle){for(const key of Object.keys(form) as Array<keyof typeof form>)form[key]=props.vehicle[key]??form[key];form.manufactureDate=date(props.vehicle.manufactureDate);form.serviceStartDate=date(props.vehicle.serviceStartDate)}}});
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{const payload={...form,manufactureDate:form.manufactureDate||undefined,serviceStartDate:form.serviceStartDate||undefined};const row=await api<any>(props.vehicle?`/archives/vehicles/${props.vehicle.id}`:'/archives/vehicles',{method:props.vehicle?'PATCH':'POST',body:JSON.stringify(payload)});ElMessage.success(props.vehicle?'车辆信息已保存':'车辆已建档');visible.value=false;emit('saved',row)}catch(e){ElMessage.error(subjectError(e))}finally{saving.value=false}}
</script>
<template><el-dialog v-model="visible" :title="vehicle?'编辑车辆':'新增车辆'" width="740px" class="subject-editor" destroy-on-close :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><el-form ref="formRef" :model="form" :rules="rules" label-position="top" class="subject-form" :disabled="saving"><el-form-item label="车辆编号" prop="businessNo"><el-input v-model="form.businessNo" placeholder="VEH-2026-031"/></el-form-item><el-form-item label="车辆名称" prop="name"><el-input v-model="form.name"/></el-form-item><el-form-item label="VIN" prop="vin"><el-input v-model="form.vin"/></el-form-item><el-form-item label="设备编号" prop="deviceNo"><el-input v-model="form.deviceNo"/></el-form-item><el-form-item label="车辆类型"><el-select aria-label="车辆类型" v-model="form.vehicleType"><el-option label="配送" value="DELIVERY"/><el-option label="环卫" value="SANITATION"/><el-option label="巡逻" value="PATROL"/><el-option label="零售" value="RETAIL"/><el-option label="接驳" value="SHUTTLE"/></el-select></el-form-item><el-form-item label="运营场景"><el-select aria-label="运营场景" v-model="form.operationScene" allow-create filterable><el-option label="城市配送" value="URBAN_DELIVERY"/><el-option label="道路环卫" value="ROAD_SANITATION"/><el-option label="园区巡逻" value="PARK_PATROL"/><el-option label="移动零售" value="MOBILE_RETAIL"/><el-option label="园区接驳" value="PARK_SHUTTLE"/></el-select></el-form-item><el-form-item label="车型" prop="modelId"><el-select aria-label="车型" v-model="form.modelId" filterable><el-option v-for="item in options.models" :key="item.id" :label="`${item.name} · ${item.modelCode}`" :value="item.id"/></el-select></el-form-item><el-form-item v-if="!isEnterprise" label="所属企业" prop="enterpriseId"><el-select aria-label="所属企业" v-model="form.enterpriseId" filterable><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="上装设备"><el-input v-model="form.upperEquipment" placeholder="货柜、清扫装置等"/></el-form-item><el-form-item label="车身颜色"><el-input v-model="form.color"/></el-form-item><el-form-item label="生产日期"><el-date-picker v-model="form.manufactureDate" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="投运日期"><el-date-picker v-model="form.serviceStartDate" value-format="YYYY-MM-DD" type="date"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存车辆</el-button></template></el-dialog></template>
